export declare const CSS_DEVICE = "\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"].dtpl-overlay{background:var(--dtpl-device-mask);}\n\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-card{\n  box-shadow:\n    inset 0 0 0 1px var(--dtpl-seam),\n    0 0 0 12px var(--dtpl-casing),\n    0 0 0 13px var(--dtpl-case-edge),\n    0 28px 72px -8px var(--dtpl-case-shadow);\n}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-card::before,\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-card::after{display:none;}\n\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-head{\n  background:var(--dtpl-casing);color:var(--dtpl-casing-ink);\n  box-shadow:inset 0 -1px 0 var(--dtpl-seam);\n}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-title>span:last-child{\n  background:var(--dtpl-brand);color:var(--dtpl-on-brand);\n  padding:2px 7px;box-shadow:inset 0 0 0 1px var(--dtpl-on-brand);\n}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-title-ico-chip{background:var(--dtpl-casing-ink);color:var(--dtpl-brand);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-close{color:var(--dtpl-casing-ink-2);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-close:hover{background:var(--dtpl-casing-hover);color:var(--dtpl-casing-ink);}\n\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-foot{\n  background:var(--dtpl-casing);\n  border-top:1px solid var(--dtpl-seam);\n}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-foot .dtpl-sync{color:var(--dtpl-casing-ink-2);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-foot .dtpl-sync-running{color:var(--dtpl-casing-ink);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-foot .dtpl-sync-error{color:var(--dtpl-casing-ink);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-foot .dtpl-sync-error .dtpl-sync-dot{background:var(--dtpl-err);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-foot .dtpl-foot-latest{color:var(--dtpl-casing-ink-2);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-rescan{border-color:var(--dtpl-casing-line);color:var(--dtpl-casing-ink);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-rescan:hover:not(:disabled){\n  background:var(--dtpl-casing-hover);border-color:var(--dtpl-casing-line);\n}\n\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-body{scrollbar-color:var(--dtpl-scrollbar) transparent;}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-body::-webkit-scrollbar-thumb{background-color:var(--dtpl-scrollbar);}\n[data-dtpl-device][data-plugin=\"dsh-tokbook\"] .dtpl-body::-webkit-scrollbar-thumb:hover{background-color:var(--dtpl-scrollbar-hover);}\n";
